 static void Capture(Camera c,string name,int w=900,int h=700){var rt=new RenderTexture(w,h,24);c.targetTexture=rt;c.Render();RenderTexture.active=rt;var t=new Texture2D(w,h,TextureFormat.RGB24,false);t.ReadPixels(new Rect(0,0,w,h),0,0);t.Apply();File.WriteAllBytes(dir+name+".png",t.EncodeToPNG());c.targetTexture=null;RenderTexture.active=null;Object.DestroyImmediate(rt);Object.DestroyImmediate(t);}
 [MenuItem("Vampire Demo/Export Design References")] public static void Run(){
 var scene=EditorSceneManager.OpenScene("Assets/Demo/Scenes/PrologueVillageLayoutReview.unity"); var cam=new GameObject("Reference Camera").AddComponent<Camera>();cam.orthographic=true;cam.orthographicSize=38;cam.transform.position=new Vector3(0,120,0);cam.transform.rotation=Quaternion.Euler(90,0,0);cam.clearFlags=CameraClearFlags.SolidColor;cam.backgroundColor=new Color(.15f,.15f,.15f);RenderSettings.fog=false;RenderSettings.ambientMode=UnityEngine.Rendering.AmbientMode.Flat;RenderSettings.ambientLight=Color.white;var sun=new GameObject("Reference Sun").AddComponent<Light>();sun.type=LightType.Directional;sun.intensity=1.3f;sun.transform.rotation=Quaternion.Euler(50,-30,0);Capture(cam,"00_完善场景俯视",1200,700);
 EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);RenderSettings.ambientMode=UnityEngine.Rendering.AmbientMode.Flat;RenderSettings.ambientLight=Color.white;cam=new GameObject("Camera").AddComponent<Camera>();cam.clearFlags=CameraClearFlags.SolidColor;cam.backgroundColor=new Color(.27f,.29f,.31f);cam.orthographic=true;sun=new GameObject("Sun").AddComponent<Light>();sun.type=LightType.Directional;sun.intensity=1.2f;sun.transform.rotation=Quaternion.Euler(50,-30,0);
 string[] folders={"Assets/Viking Village/Prefabs/Buildings","Assets/Demo/ThirdParty/VillageBuildings/FBX"};foreach(string folder in folders){string[] guids=AssetDatabase.FindAssets("t:GameObject",new[]{folder});int n=0;foreach(string guid in guids){string path=AssetDatabase.GUIDToAssetPath(guid);string filename=Path.GetFileNameWithoutExtension(path);if(folder.Contains("Viking")&&(filename.EndsWith("_low")|| !filename.Contains("house")))continue;if(!folder.Contains("Viking")&&!path.EndsWith(".fbx",System.StringComparison.OrdinalIgnoreCase))continue;var asset=AssetDatabase.LoadAssetAtPath<GameObject>(path);if(!asset)continue;var go=Object.Instantiate(asset);var renderers=go.GetComponentsInChildren<Renderer>();if(renderers.Length==0){Object.DestroyImmediate(go);continue;}Bounds b=renderers[0].bounds;foreach(var r in renderers)b.Encapsulate(r.bounds);float size=Mathf.Max(b.size.x,b.size.y,b.size.z);cam.orthographicSize=size*.8f;cam.transform.position=b.center+new Vector3(1,.75f,-1).normalized*size*2;cam.transform.LookAt(b.center);cam.farClipPlane=size*10+100;Capture(cam,(folder.Contains("Viking")?"Viking_":"其他建筑_")+filename);Object.DestroyImmediate(go);n++;}Debug.Log("EXPORTED "+folder+" "+n);}
